document.title=`一局一江湖 · v${GAME_VERSION}`;
const $=s=>document.querySelector(s), SAVE='yiju-jianghu-v1';
const escapeHTML=text=>String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
