let toastTimer,combatBusy=false,inspectedCard=null,mapViewChapter=null;
function validSave(s){
 if(!s||![1,2,3,4,5,SAVE_VERSION].includes(s.version)||!Array.isArray(s.deck)||!s.deck.every(c=>CARD[c.id]&&Number.isInteger(c.uid))||!Array.isArray(s.relics)||!s.relics.every(id=>RELIC[id])||!Number.isFinite(s.hp)||!Number.isFinite(s.rng)||!Number.isInteger(s.step)||s.step<0||s.step>(s.journey?45:18)||!validJourney(s))return false;
 if(!['character','opening','draft','map','battle','reward','rest','shop','event','treasure','win','lost'].includes(s.phase))return false;
 if((s.player!==undefined||s.version===SAVE_VERSION)&&!validPlayer(s.player))return false;
 if(s.phase==='treasure'&&(!s.scene||!Array.isArray(s.scene.relics)||s.scene.relics.length>2||!s.scene.relics.every(id=>RELIC[id])||!(s.scene.claimed===null||typeof s.scene.claimed==='string')))return false;
 if(s.phase==='character'&&!validCharacterDraft(s.character))return false;
 const phase=s.phase==='character'&&s.character.editing?s.character.returnPhase:s.phase;
 if(phase==='opening'&&(s.step!==0||!validOpening(s.opening)))return false;
 if(phase==='draft'&&(s.deck.length>10||!s.deck.every(c=>CARDS.some(d=>d.id===c.id)&&!c.up)||!s.deck.filter(c=>CARD[c.id].type==='p').every((c,i,a)=>a.findIndex(x=>x.id===c.id)===i)))return false;
 if(s.b&&(!Array.isArray(s.b.hand)||!s.b.hand.every(c=>CARD[c.id])))return false;
 if(phase==='battle'&&(!s.b||!Array.isArray(s.b.enemies)||!s.b.enemies.length))return false;
 return true;
}
try{const s=JSON.parse(localStorage.getItem(SAVE));if(validSave(s))game=new Game(s);}catch{}
function save(){if(!game.s)return;try{localStorage.setItem(SAVE,JSON.stringify(game.s));saveError=false;}catch{saveError=true;}}
function toast(text){const t=$('#toast');t.textContent=text;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600);}
const mountain=`<svg class="mountain-bg" viewBox="0 0 1000 650" width="100%" height="100%" preserveAspectRatio="xMidYMax slice" aria-hidden="true"><defs><linearGradient id="mist" x2="0" y2="1"><stop stop-color="#76816b" stop-opacity=".12"/><stop offset="1" stop-color="#94a381" stop-opacity=".8"/></linearGradient></defs><circle cx="660" cy="128" r="62" fill="#bba57b" opacity=".25"/><path d="M0 470 125 320 204 385 376 120 474 270 532 230 709 440 805 280 1000 470V650H0Z" fill="url(#mist)"/><path d="m245 650 128-255 90 90 129-227 131 220 64-70 213 235v57z" fill="#52694f" opacity=".7"/><path d="m0 570 145-135 165 150 150-75 157 110 180-126 203 80v76H0Z" fill="#243c2b"/><path d="m565 226 30 21-5 49 23 14-20 50 55 68-51-39 5-66-37-20 16-32z" fill="#b4b79c" opacity=".14"/><path d="M-50 530Q300 480 550 540T1100 505M-50 560Q300 510 600 570T1100 550" fill="none" stroke="#bbc4a5" stroke-width="10" opacity=".09"/></svg>`;
function figure(enemy=false){return `<svg class="figure" viewBox="0 0 120 160" aria-hidden="true"><ellipse cx="60" cy="151" rx="35" ry="5" fill="#080e0b" opacity=".4"/><path d="M77 48 98 8 103 12 82 56" fill="#9b9d85"/><path d="m80 46 11 7" stroke="#c4a569" stroke-width="4"/><path d="m48 104-9 43 14 2 12-34 10 33 15-2-13-45" fill="#141c18"/><path d="M40 50Q61 39 79 53L88 112Q60 124 30 111Z" fill="${enemy?'#684c3c':'#60795e'}"/><path d="m44 57-20 38 12 8 20-27m19-17 20 32-9 8-24-28" fill="${enemy?'#7f5e48':'#819076'}"/><path d="m49 48 12 20 13-20-4 40-18-2" fill="#c4b997" opacity=".65"/><path d="M36 96 83 93" stroke="#282e23" stroke-width="8"/><path d="m63 98 31 17" stroke="#8c3d30" stroke-width="4"/><ellipse cx="60" cy="31" rx="14" ry="17" fill="#c1ac86"/><path d="M45 29Q42 6 61 8Q81 7 76 33L72 21 48 24" fill="#17201a"/><path d="m35 25 26-18 26 18-30 4z" fill="${enemy?'#3e3f2d':'#3d4d36'}"/><path d="m61 12-6-9" stroke="#16201a" stroke-width="7"/></svg>`;}
function playerFigure(profile=game.s.player,extra=''){const p=PLAYER[profile.portrait];return `<img class="player-art ${extra}" src="${p.art}" alt="${p.title}立绘" width="200" height="280" draggable="false">`;}
function characterPage(){
 const c=game.s.character,p=PLAYER[c.portrait],name=cleanPlayerName(c.name),error=game.characterError();
 return `<div class="heading"><div><div class="eyebrow">${c.editing?'侠客档案 · 更名易容':'初入江湖 · 创建侠客'}</div><h2>${c.editing?'换一身行装，仍是你的江湖':'你的名字，从此写入江湖'}</h2><p>立绘仅影响外观，男女角色的初始牌组与属性相同。</p></div></div><div class="character-layout"><aside class="hero-preview info-box" aria-label="侠客形象预览">${p?playerFigure({portrait:p.id}):'<div class="hero-empty"><span>侠</span><p>选择一张立绘<br>让江湖记住你的模样</p></div>'}<h3 id="hero-preview-name">${escapeHTML(name||'待署侠名')}</h3><small>${p?p.title+' · '+(p.gender==='male'?'男':'女'):'男女各三款 · 自由选择'}</small></aside><section class="character-form" aria-label="起名与立绘选择"><label class="name-label" for="hero-name">侠客姓名</label><div class="name-input-row"><input id="hero-name" aria-label="侠客姓名" value="${escapeHTML(c.name)}" maxlength="24" placeholder="给你的侠客起个名字" autocomplete="off" spellcheck="false" aria-describedby="hero-name-help"><span id="hero-name-count">${Array.from(name).length} / 12</span></div><small id="hero-name-help">1—12个字，支持中文、英文和数字。</small><div class="gender-tabs" role="group" aria-label="立绘性别"><button data-action="hero-gender" data-id="male" aria-pressed="${heroGender==='male'}">男性 · 3款</button><button data-action="hero-gender" data-id="female" aria-pressed="${heroGender==='female'}">女性 · 3款</button></div><div class="portrait-grid">${PLAYERS.filter(d=>d.gender===heroGender).map(d=>`<button class="portrait-choice ${d.id===c.portrait?'selected':''}" data-action="hero-portrait" data-id="${d.id}" aria-label="选择${d.title}（${d.gender==='male'?'男':'女'}）" aria-pressed="${d.id===c.portrait}">${playerFigure({portrait:d.id})}<strong>${d.title}</strong><small>${d.description}</small><span>${d.id===c.portrait?'已选择':'选择立绘'}</span></button>`).join('')}</div><div class="character-footer"><span id="hero-form-error" class="muted" aria-live="polite">${escapeHTML(error||'姓名与立绘已就绪')}</span><div>${c.editing?'<button data-action="hero-cancel">取消修改</button>':''}<button class="primary" id="hero-confirm" data-action="hero-confirm" ${error?'disabled':''}>${c.editing?'保存姓名与立绘':'确认侠客，领取机缘 →'}</button></div></div></section></div>`;
}
function foldedTitle(name){const chars=Array.from(name),rows=game.s?.b?.hand.length>=6?5:4;return Array.from({length:Math.ceil(chars.length/rows)},(_,i)=>`<span class="folded-column">${escapeHTML(chars.slice(i*rows,(i+1)*rows).join(''))}</span>`).join('');}
function cardHTML(c,{action='',uid=null,read=false,battle=false,choice=false}={}){
 const d=CARD[c.id],rar=d.rarity,art=cardArtwork(c.id),folded=battle&&!read&&!choice&&action==='play'&&matchMedia('(max-width:900px)').matches;let cost=Array.isArray(d.cost)?d.cost[c.up?1:0]:d.cost;if(battle)cost=d.cost==='X'?'X':game.cost(c);if(cost===99)cost='—';
 const reason=battle?game.reason(c):'',inspectable=battle&&!read&&matchMedia('(max-width:900px)').matches,label=`${d.name}${c.up?'·精进':''}`;
 const attr=action?`data-action="${action}" ${uid!==null?`data-uid="${uid}"`:''} data-id="${d.id}"`:'';
 return `<${read?'article':'button'} class="card ${d.type} r${rar} ${c.up?'up':''} ${read?'readonly':''} ${inspectable&&reason?'unavailable':''} ${inspectable&&inspectedCard===c.uid?'inspected':''} ${choice&&selected.includes(c.uid)?'selected':''}" ${attr} ${battle&&reason&&!read&&!inspectable?'disabled':''} ${inspectable?`aria-expanded="${inspectedCard===c.uid}"`:''} ${!read?`aria-label="${label}${battle&&reason?'，'+reason:''}"`:''}>
 <span class="cost">${cost}</span><div class="type">${TYPE[d.type]}${c.up?' · 精进':''}</div><h3>${label}</h3>${battle&&!read?`<span class="folded-name" aria-hidden="true">${foldedTitle(d.name)}${c.up?'<small>精进</small>':''}</span>`:''}${!folded&&art?`<img class="card-art" src="${art.art}" alt="${art.label}意境插画" width="480" height="320" loading="${battle&&read?'eager':'lazy'}" decoding="async" draggable="false">`:''}<div class="description">${describe(c)}</div><footer><span>${d.path}</span><span>${RARITY[rar]||''}</span></footer>${read?`<div class="card-source">${d.source}</div>`:''}${battle&&reason?`<div class="unplayable">${reason}</div>`:''}</${read?'article':'button'}>`;
}
function relicHTML(id,action='',extra=''){const r=RELIC[id];return `<${action?'button':'article'} class="relic-option" ${action?`data-action="${action}" data-id="${id}"`:''} ${extra}><div class="relic-option-head">${relicIcon(id)}<div><div class="eyebrow">${['初始','随身','珍奇','镇派'][r.tier]}</div><h3>${r.name}</h3></div></div><p>${r.text}</p><small>${r.source}</small></${action?'button':'article'}>`;}
function home(){
 const resumable=!!game.s,profile=resumable?`${escapeHTML(game.s.player.name)} · 第${game.chapter+1}章 · ${Math.min(game.s.step+1,game.totalSteps)}/${game.totalSteps}程`:'十招起步，沿途习武，自成一家';
 return `<div class="home"><nav class="home-nav" aria-label="首页导航"><div class="brand"><span class="seal">侠</span><div><strong>一局江湖</strong><small>武侠卡牌冒险</small></div></div><div class="home-links"><button class="small" data-action="enemy-book">群敌录</button><button class="small" data-action="catalogue">图鉴 ↗</button></div></nav><section class="home-hero" aria-label="一局江湖封面"><img class="home-cover" src="${cardArtwork('W03').art}" alt="群山云海间的仗剑侠客" width="480" height="320" fetchpriority="high" decoding="async"><div class="home-cover-copy"><div class="eyebrow">以牌入江湖 · 以武问山河</div><h1><span>一局</span><span>一江湖</span></h1><p>从无名侠客，到华山论剑。</p></div><span class="home-cover-note" aria-hidden="true">牌由你组 · 路由你行</span></section><section class="home-entry" aria-label="开始冒险"><button class="primary home-start" data-action="${resumable?'continue':'new'}"><span><strong>${resumable?'继续此局':'踏入江湖'}</strong><small>${profile}</small></span><b aria-hidden="true">↗</b></button><div class="intro-actions">${resumable?'<button data-action="new">另启新程</button>':''}<button data-action="help">初入须知</button></div></section><section class="home-bottom" aria-label="江湖一览"><div><strong>80<small> 招</small></strong><span>武学技法</span></div><div><strong>30<small> 件</small></strong><span>随身奇物</span></div><div><strong>45<small> 程</small></strong><span>三章江湖</span></div></section><footer class="home-footer"><span>一局一江湖，取舍皆由你</span><span>v${GAME_VERSION} · 自动存档</span></footer></div>`;
}
function header(){const s=game.s;return `<header class="topbar"><div class="stats"><span class="mobile-brand">江湖</span><span class="hp">气血 <strong>${s.hp}</strong><small> / ${s.maxHp}</small></span><span class="gold-stat">银两 <strong>${s.gold}</strong></span><span>行程 <strong>${Math.min(s.step+1,game.totalSteps)}</strong><small> / ${game.totalSteps}</small></span></div><div class="top-actions"><span class="build-badge" aria-label="游戏版本 v${GAME_VERSION}">v${GAME_VERSION}</span><button class="small" data-action="deck">牌组 ${s.deck.length}</button><button class="small" data-action="relics">奇物 ${s.relics.length}</button><button class="small desktop-only" data-action="help">须知</button><button class="small" data-action="menu">菜单</button></div></header>`;}
function sidebar(){const s=game.s,ch=CHAPTERS[game.chapter];return `<aside class="side"><div class="brand"><span class="seal">侠</span><div><strong>一局江湖</strong><small>A MARTIAL JOURNEY</small></div></div><div class="side-chapter"><span class="eyebrow">第 ${game.chapter+1} 章 / 共三章</span><h3>${ch.name}</h3><small>${ch.place}</small><div class="journey-bar">${Array.from({length:game.totalSteps},(_,i)=>`<i class="${i<s.step?'done':''}"></i>`).join('')}</div></div><nav><button data-action="map"><b>⌁</b> 江湖行程</button><button data-action="deck"><b>▤</b> 我的武学 <small>${s.deck.length}</small></button><button data-action="relics"><b>◇</b> 随身奇物 <small>${s.relics.length}</small></button><button data-action="catalogue"><b>冊</b> 武学图鉴</button><button data-action="edit-player"><b>侠</b> 姓名与立绘</button><button data-action="enemy-book"><b>劍</b> 江湖群敌</button><button data-action="help"><b>?</b> 初入须知</button></nav><div class="side-foot">${ch.quote}<br>牌由你组，路由你行<br><span class="version">v${GAME_VERSION} · ${saveError?'存档受限':'进度已自动保存'}</span></div></aside>`;}
function mapBoard(interactive=true){
 const s=game.s,ch=mapViewChapter??game.chapter,map=game.chapterMap(ch),height=map.rows.length*96+210,base=ch*game.chapterLength;
 const visited=new Set(s.journey?s.journey.path:s.history.filter(h=>Math.floor(h.step/6)===ch).map(h=>map.rows[h.step%6].find(n=>n.kind===h.kind)?.id));
 const active=s.journey?.active||(!s.journey&&game.chapter===ch&&s.phase!=='map'?map.rows[game.chapterStep].find(n=>n.kind===s.scene?.kind)?.id:null);
 const available=new Set(interactive&&ch===game.chapter?game.availableNodes.map(n=>n.id):[]),byId=Object.fromEntries(map.nodes.map(n=>[n.id,n]));
 const point=n=>({x:n.x*7.2,y:height-125-n.floor*96+(n.yOffset||0)});
 const edgeHTML=map.edges.map(([a,b])=>{const p=point(byId[a]),q=point(byId[b]),walked=visited.has(a)&&(visited.has(b)||b===active),next=visited.has(a)&&available.has(b);return `<path class="travel-road ${walked?'walked':next?'next':''}" d="M${p.x} ${p.y}C${p.x} ${p.y-48} ${q.x} ${q.y+48} ${q.x} ${q.y}"/>`;}).join('');
 const focus=map.nodes.find(n=>available.has(n.id))||byId[active]||map.rows[0][0],here=s.journey?.path.at(-1);
 return `<section class="travel-map" aria-label="${CHAPTERS[ch].name}行路图"><div class="travel-map-toolbar"><div class="travel-chapters" role="group" aria-label="查看章节地图">${CHAPTERS.map((c,i)=>`<button data-action="map-chapter" data-key="${i}" aria-pressed="${i===ch}" aria-label="查看第${i+1}章${c.name}"><small>第${i+1}章</small><span>${c.name}</span>${i<game.chapter?'<i>已过</i>':i===game.chapter?'<i>此行</i>':''}</button>`).join('')}</div><button class="quiet small map-locate" data-action="map-locate">定位此行 ⌖</button></div><div class="travel-map-scroll" tabindex="0" aria-label="上下滚动查看江湖路线" data-map-key="${ch}" data-map-focus="${point(focus).y}"><div class="travel-canvas" style="height:${height}px">${travelTerrain(ch,height)}<svg class="travel-roads" viewBox="0 0 720 ${height}" preserveAspectRatio="none" aria-hidden="true">${edgeHTML}</svg><div class="map-compass" aria-hidden="true">北<span>✧</span></div><div class="travel-destination"><span>第${ch+1}章 · ${map.rows.length}程</span><strong>${ch===0?'青城山门':ch===1?'星宿石台':'华山绝顶'}</strong><small>守关 · ${CHAPTERS[ch].boss}</small></div>${[3,8,12].filter(i=>i<map.rows.length-1).map((floor,i)=>`<span class="travel-area" style="top:${height-125-floor*96}px;${i%2?'right:4%':'left:4%'}">${[['烟雨水乡','古道深处','山门在望'],['中州旷野','群山藏锋','险峰之上'],['云起西岳','栈道悬空','剑指绝巅']][ch][i]}</span>`).join('')}${map.nodes.map(n=>{const pos=point(n),done=visited.has(n.id),open=available.has(n.id),isHere=n.id===active||n.id===here,passed=base+n.floor<s.step;return `<button class="travel-node kind-${n.kind} ${done?'visited':passed?'bypassed':''} ${open?'available':''} ${isHere?'here':''}" style="left:${n.x}%;top:${pos.y}px" data-action="enter-node" data-id="${n.id}" ${!open?'disabled':''} aria-label="${n.name} · ${NODE_NAMES[n.kind]}${open?' · 可前往':done?' · 已走过':isHere?' · 当前地点':' · 暂不可达'}"><span class="travel-node-mark">${travelMark(n.kind)}${done?'<i>✓</i>':''}</span><strong>${n.kind==='boss'?CHAPTERS[ch].boss:n.name}</strong><small>${NODE_NAMES[n.kind]}</small></button>`;}).join('')}<div class="travel-origin"><span>此行始于</span><strong>${CHAPTERS[ch].place}</strong></div></div></div><div class="travel-legend"><span><i class="legend-current"></i>可前往</span><span><i class="legend-done"></i>已走过</span><span>沿相连的路向上行进</span></div></section>`;
}
function openingPage(){
 const o=game.s.opening,option=o.options.find(x=>x.id===o.selected),d=OPENING_BOONS.find(x=>x.id===o.selected);
 const intro=`<div class="eyebrow">初次出山 · 山门赠别</div><h2>临行之前，一份机缘</h2><p>十招基础武学，一只粗布药囊。<br>山中老者为你备下四份机缘，任选其一，再入江湖。</p>`;
 if(o.result){
  const extra=['relicWound','relicCurse'].includes(option.id)?relicHTML(option.relic):option.id==='rareToll'?cardHTML({id:option.card},{read:true}):'';
  return `<div class="center-box opening-page">${intro}<div class="opening-result info-box"><span class="eyebrow">${d.title} · 已领取</span><h3>${escapeHTML(o.result)}</h3>${extra}</div><button class="primary" data-action="opening-leave">带上机缘，踏入江湖 →</button></div>`;
 }
 if(option){
  const cards=option.id==='insight'?option.cards.map(id=>({id,up:false})):game.s.deck.filter(c=>option.id!=='refine'||!c.up);
  return `<div class="opening-page"><div class="heading"><div><div class="eyebrow">山门赠别 · ${d.title}</div><h2>${option.id==='refine'?'选择一张牌，永久精进':option.id==='simplify'?'选择一张牌，永久移除':'三卷残篇，取其一'}</h2><p>${option.id==='refine'?'下方预览精进后的效果。选定后立即生效。':d.text}</p></div><button data-action="opening-back">返回重选</button></div><div class="collection opening-cards">${cards.map(c=>cardHTML(option.id==='refine'?{...c,up:true}:c,{action:'opening-card',uid:c.uid??null})).join('')}</div></div>`;
 }
 return `<div class="center-box opening-page">${intro}<div class="opening-options">${o.options.map((x,i)=>{const boon=OPENING_BOONS.find(d=>d.id===x.id);return `<button class="opening-option" data-action="opening-choice" data-id="${x.id}" aria-label="选择${boon.title}"><span class="opening-number">0${i+1}</span><span class="tag ${boon.risk?'':'gold'}">${boon.risk?'有代价':'赠礼'}</span><h3>${boon.title}</h3><p>${boon.text}</p><small>选择这份机缘 →</small></button>`;}).join('')}</div><small>每局随机生成，仅可领取一份；选择不会影响后续奖励的流派。</small></div>`;
}
function mapPage(){
 const s=game.s,ch=CHAPTERS[game.chapter],next=game.availableNodes,kinds=[...new Set(next.map(n=>NODE_NAMES[n.kind]))];
 return `<div class="heading travel-heading"><div><div class="eyebrow">江湖行路图 · 第${game.chapter+1}章 / 共三章</div><h2>${ch.name}<small>第 ${game.chapterStep+1} / ${game.chapterLength} 程</small></h2><p>${s.journey?'山川有路，取舍由你。每次岔路，通向不同的江湖。':'旧局沿原十八程续行，当前进度完整保留；新局开启四十五程长途。'}</p></div></div><div class="travel-layout">${mapBoard()}<aside class="travel-summary"><section class="info-box"><span class="eyebrow">下一站</span><h3>${kinds.join(' / ')}</h3><p>点击地图上亮起的地点启程，其他路线将随你的选择展开。</p><div class="travel-progress"><span>走过 ${s.step} 程</span><span>全程 ${game.totalSteps} 程</span><i><b style="width:${s.step/game.totalSteps*100}%"></b></i></div></section><section class="info-box travel-belongings"><span class="eyebrow">此行行囊</span><h3>${s.deck.length} 招武学 · ${s.relics.length} 件奇物</h3><div class="relic-strip">${s.relics.slice(-5).map(id=>`<button class="relic-token" data-action="relic-detail" data-id="${id}">${relicIcon(id)}<span>${RELIC[id].name}</span></button>`).join('')}</div><small>途中的宝物与机缘，皆可助你自成一家。</small></section><section class="travel-tip"><strong>行路有节</strong><p>高手守着险路，歇脚留待蓄力。每章中途可探遗藏，山门之前可作整备。</p><small>${ch.quote}</small></section></aside></div>`;
}
function statusHTML(){const b=game.s.b;return `${b.str?`<span class="status-chip">劲力 ${b.str}</span>`:''}${b.weak?`<span class="status-chip red">虚弱 ${b.weak}</span>`:''}${b.vuln?`<span class="status-chip red">破绽 ${b.vuln}</span>`:''}${b.poison?`<span class="status-chip red" title="敌方行动结束后失去等量气血，随后中毒减少1">中毒 ${b.poison}</span>`:''}${b.qiPenalty?`<span class="status-chip red">寒气 · 真气−${b.qiPenalty}</span>`:''}${b.repeat?'<span class="status-chip">互搏待发</span>':''}${b.discount?'<span class="status-chip">技法减费1</span>':''}`;}
function intentDamage(e){const first=game.previewEnemy(e),rest=game.previewEnemy(e,1),hits=e.intent.hits||1;if(hits===1)return String(first);if(first===rest)return `${first} × ${hits}`;return `${first} + ${rest}${hits>2?' × '+(hits-1):''}`;}
function enemyFigure(e){const d=ENEMY[e.id];return d?`<img class="enemy-art" src="${d.art}" alt="${d.name}立绘" width="200" height="250" draggable="false">`:figure(true);}
function moveText(i){return [i.damage?i.damage+'伤害'+(i.hits?' × '+i.hits:''):'',i.block?'格挡+'+i.block:'',i.str?'劲力+'+i.str:'',i.status?'气滞×'+i.status:'',i.weak?'虚弱'+i.weak:'',i.vuln?'破绽'+i.vuln:'',i.poison?'中毒+'+i.poison:'',i.chill?'下回合真气−'+i.chill:'',i.leech?'伤及气血后回复至多'+i.leech:'',i.allyBlock?'同伴格挡+'+i.allyBlock:'',i.charge?'下次攻击蓄力+'+i.charge:'',i.combo?'同伴存活时伤害+'+i.combo:''].filter(Boolean).join(' · ');}
function intentExtra(e){const i=e.intent;return [i.block?'格挡+'+i.block:'',i.str?'劲力+'+i.str:'',i.status?'气滞×'+i.status:'',i.weak?'虚弱'+i.weak:'',i.vuln?'破绽'+i.vuln:'',i.poison?'中毒+'+i.poison:'',i.chill?'下回合真气−'+i.chill:'',i.leech?'伤血吸血≤'+i.leech:'',i.allyBlock?'同伴格挡+'+i.allyBlock:'',i.charge?'蓄力+'+i.charge:'',i.combo&&game.s.b.enemies.some(x=>x.id===i.partner&&x.hp>0)?'合击生效':''].filter(Boolean).join(' · ');}
function handPreview(){
 const c=game.s.b.hand.find(x=>x.uid===inspectedCard);if(!c)return '';
 const d=CARD[c.id],reason=game.reason(c),enemy=game.s.b.enemies.find(e=>e.key===target&&e.hp>0)||game.s.b.enemies.find(e=>e.hp>0);
 return `<section class="hand-preview" role="region" aria-label="${d.name} · 完整牌面"><div class="hand-preview-head"><span>武学详情 · ${TYPE[d.type]}</span><button class="quiet small" data-action="close-card-preview" aria-label="收起牌面">✕</button></div>${cardHTML(c,{read:true,battle:true})}<div class="hand-preview-action"><small>${reason|| (d.type==='a'?'目标：'+(enemy?.name||'无'):'看清效果，再出招')}</small><button class="primary" data-action="play-inspected" data-uid="${c.uid}" ${reason?'disabled':''}>${reason?'暂不能出招':'出招 →'}</button></div></section>`;
}
function vitalsHTML(hp,maxHp,block){
 const safeHp=Math.max(0,hp),safeBlock=Math.max(0,block||0),blockMax=Math.max(maxHp,safeBlock);
 return `<div class="combat-vitals"><div class="health-bar" role="meter" aria-label="气血" aria-valuemin="0" aria-valuemax="${maxHp}" aria-valuenow="${safeHp}"><span style="width:${safeHp/maxHp*100}%"></span><b>气血 ${safeHp} / ${maxHp}</b></div><div class="block-bar" role="meter" aria-label="格挡" aria-valuemin="0" aria-valuemax="${blockMax}" aria-valuenow="${safeBlock}" title="格挡 ${safeBlock}"><span style="width:${Math.min(100,safeBlock/maxHp*100)}%"></span><b>格挡 ${safeBlock}</b></div></div>`;
}
function battlePage(){const s=game.s,b=s.b;if(!b.enemies.some(e=>e.key===target&&e.hp>0))target=b.enemies.find(e=>e.hp>0)?.key||0;
 return `<div class="battle-top"><span class="eyebrow">${escapeHTML(s.scene?.place||CHAPTERS[game.chapter].place)}${b.formation?' · '+b.formation:''}</span><span class="round">第 ${b.turn} 回合</span><span class="tag">${NODE_NAMES[b.kind]} · ${b.enemies.filter(e=>e.hp>0).length}人</span><button class="quiet small" data-action="enemy-book">敌人招式</button><button class="quiet small" data-action="battle-log">查看战报</button></div>${b.openDart?'<div class="info-box" style="padding:12px;margin-bottom:15px">金蛇锥待发：先选中一名敌人，再 <button class="small gold-btn" data-action="dart">投出金蛇锥 · 8伤害</button></div>':''}<div class="battlefield" data-enemies="${b.enemies.length}"><div class="player"><div class="fighter-intent player-intent"><span>你的回合</span><small>见招拆招，自成一派</small></div>${playerFigure()}<div class="player-details"><div class="player-name">${escapeHTML(s.player.name)}</div>${vitalsHTML(s.hp,s.maxHp,b.block)}<div class="status-row">${statusHTML()}</div></div></div><div class="enemies">${b.enemies.map(e=>`<button class="enemy rank-${ENEMY[e.id]?.rank||'normal'} ${e.hp<=0?'dead':''} ${e.key===target?'selected':''}" data-action="target" data-key="${e.key}" aria-label="选中${e.name}" ${e.hp<=0?'disabled':''}><span class="target-marker">${e.key===target?'已选中 ':''}${e.callSign||''}</span><div class="fighter-intent"><div class="intent">${e.hp>0?e.intent.damage?`${e.intent.label}　<span class="damage">${intentDamage(e)}</span>`:e.intent.label:'已击败'}</div><div class="enemy-extra">${e.hp>0?intentExtra(e):''}</div></div>${enemyFigure(e)}<h3>${ENEMY[e.id]?.name||e.name}</h3><span class="enemy-faction">${ENEMY[e.id]?.faction||''}${e.role?' · '+e.role:''}${e.enraged?' · 逆练阶段':''}</span>${vitalsHTML(e.hp,e.maxHp,e.block)}<div class="status-row">${e.str?`<span class="status-chip">劲力 ${e.str}</span>`:''}${e.weak?`<span class="status-chip red">虚弱 ${e.weak}</span>`:''}${e.vuln?`<span class="status-chip red">破绽 ${e.vuln}</span>`:''}${e.charge?`<span class="status-chip">蓄力 ${e.charge}</span>`:''}${e.pin?`<span class="status-chip">首击−${e.pin}</span>`:''}</div></button>`).join('')}</div></div><div class="powers">${Object.entries(b.powers).map(([id,up])=>`<span class="power" title="${describe({id,up})}">${CARD[id].name}${up?'⁺':''}</span>`).join('')||'<small>尚未运起心法</small>'}</div>${handPreview()}<div class="battle-bottom"><div class="hand-panel"><div class="hand-title"><span>手牌 ${b.hand.length} / 10 · ${matchMedia('(max-width:900px)').matches?'点牌展开，再确认出招':'点击武学出招'}</span><button class="quiet small hand-inspect" data-action="pile" data-id="hand" aria-label="查看手牌完整说明">完整说明 ↗</button></div><div class="hand" style="--hand-count:${Math.max(1,b.hand.length)}" data-count="${b.hand.length}">${b.hand.map(c=>cardHTML(c,{action:'play',uid:c.uid,battle:true})).join('')||'<div class="empty">手中无招，静待下一回合。</div>'}</div><div class="battle-help">${game.has('R29')?'广陵散：攻击 '+b.turnFlags.attacks+'/2　':''}${game.has('R30')?'鸳鸯刀：出牌 '+b.turnFlags.plays+'/8　':''}消耗仅本场有效。卡牌自损无法用格挡抵挡。</div></div><div class="turn-panel"><div class="turn-controls" role="group" aria-label="回合操作"><div class="energy"><div class="energy-orb">${b.qi}</div><div><span>真气</span><small>每回合回复至 ${game.qiMax}</small></div></div><button class="primary" data-action="end-turn">结束回合 →</button></div><button class="small" data-action="auto-turn">辅助出招一回合</button><div class="piles"><button data-action="pile" data-id="draw">抽牌 ${b.draw.length}</button><button data-action="pile" data-id="discard">弃牌 ${b.discard.length}</button><button data-action="pile" data-id="exhaust">消耗 ${b.exhaust.length}</button></div></div></div><details class="combat-log"><summary>本场战报 · 最近行动</summary><div class="log-lines">${b.log.slice(-18).reverse().map(x=>`<div>${x}</div>`).join('')}</div></details>`;
}
function rewardPage(){const r=game.s.reward;return `<div class="center-box"><div class="eyebrow">${r.boss?'一章告捷':'交锋获胜'}</div><h2>${r.boss?'此山已过，前路仍长':'武有所悟'}</h2><p>银两 +${r.gold} · 药囊已回复气血${r.boss?' · 离开时进行章节整备':''}</p><div class="section-label">选择一张武学，或有所取舍</div>${r.cardDone?'<div class="reward-confirmed">武学奖励已处理</div>':`<div class="reward-cards">${r.cards.map(id=>cardHTML({id,up:false},{action:'take-card'})).join('')}</div><button class="quiet small" data-action="skip-card">跳过武学</button>`}${r.relics.length?`<div class="section-label">${r.boss?'选择一件镇派奇物 · 留意代价':'高手所藏 · 奇物奖励'}</div>${r.relicDone?'<div class="reward-confirmed">奇物奖励已处理</div>':`<div class="relic-options">${r.relics.map(id=>relicHTML(id,'take-relic')).join('')}</div><button class="quiet small" data-action="skip-relic">放弃奇物</button>`}`:''}<div style="margin-top:30px"><button class="primary" data-action="leave-reward" ${!r.cardDone||!r.relicDone?'disabled':''}>${game.s.step===game.totalSteps-1?'完成论剑，查看此局':'收拾行囊，继续前行'} →</button></div></div>`;}
const events={master:{glyph:'师',title:'松下遇高人',text:'青衫老者看过你的拳路，微微颔首：“招式有形，心意无穷。”',options:[['请教武学','从全体武学中随机习得一张，流派不限。'],['融会旧招','随机永久精进一张非基础武学。']]},shrine:{glyph:'缘',title:'破庙藏珍',text:'佛座之下藏着一件旧物。取与不取，皆在一念之间。',options:[['取走奇物','获得一件奇物；永久牌组加入一张心魔。'],['静坐片刻','回复12气血。']]},traveller:{glyph:'药',title:'药香过渡口',text:'行医人背着药箱走过石桥，愿以一剂养元方与你结缘。',options:[['购入养元方','支付35银两，气血上限+8，并回复8气血。'],['护送一程','获得35银两。']]},cliff:{glyph:'崖',title:'绝壁留书',text:'山风拨开藤蔓，石壁上露出半页武学。要看分明，须冒些险。',options:[['攀崖求书','失去6气血，获得一张随机绝学。'],['沿路而行','获得25银两。']]}};
Object.assign(events,{
 clinic:{glyph:'药',title:'山野药庐',text:'竹门半掩，炉上药香正浓。老医者看你一路风尘，推来一盏温茶。',options:[['求一剂汤药','支付25银两，回复18气血。'],['清泉洗尘','不花银两，回复6气血。']]},
 cache:{glyph:'匣',title:'行脚人的旧匣',text:'桥边老者守着一只旧木匣，说是多年行走江湖留下的随身之物。',options:[['买下旧匣','支付55银两，获得一件随机随身奇物。'],['搭一把手','帮老者搬运旧箱，获得20银两。']]},
 stone:{glyph:'碑',title:'残碑悟武',text:'苔痕之下留着数行拳理。山风过处，你忽然看出那些旧招还有未尽之意。',options:[['参悟攻招','随机永久精进一张尚未精进的攻击牌。'],['揣摩技法','随机永久精进一张尚未精进的技法牌。']]},
 ferry:{glyph:'渡',title:'渡口试手',text:'船家把长篙往岸边一横，笑道：“江上风浪不小，先让我看看你的身手。”',options:[['切磋几招','失去5气血，获得一张随机优质武学。'],['撑篙渡人','替船家撑篙一程，获得20银两。']]}
});
function treasurePage(){const sc=game.s.scene;return `<div class="center-box treasure-page"><div class="eyebrow">${escapeHTML(sc.place||'江湖遗藏')} · 山水有馈</div><div class="treasure-emblem">${travelMark('treasure')}</div><h2>尘封旧藏，今日逢君</h2><p>石匣中的旧物仍有余温。取一件助你行路，或带些银两，皆是机缘。</p>${sc.claimed?`<div class="reward-confirmed">${escapeHTML(sc.claimed)}</div><button class="primary" data-action="finish-node">收起行囊，继续赶路 →</button>`:`<div class="relic-options">${sc.relics.map(id=>relicHTML(id,'take-treasure')).join('')}</div><button class="treasure-coins" data-action="take-treasure" data-id="coins"><strong>取走银两 · 65</strong><small>不取奇物，留作沿途所需。</small></button>`}</div>`;}
function eventPage(){const s=game.s,sc=s.scene,e=events[sc.event];return `<div class="center-box"><div class="eyebrow">${escapeHTML(sc.place||CHAPTERS[game.chapter].place)} · 江湖奇遇</div><div class="event-scene">${e.glyph}</div><h2>${e.title}</h2><p>${e.text}</p>${sc.result?`<div class="reward-confirmed">${sc.result}</div><button class="primary" data-action="finish-node">继续赶路 →</button>`:`<div class="choices">${e.options.map(([title,text],i)=>{const disabled=i===0&&sc.event==='clinic'&&s.gold<25||i===0&&sc.event==='cache'&&(s.gold<55||!RELICS.some(r=>r.tier===1&&!s.relics.includes(r.id)))||i===0&&sc.event==='ferry'&&s.hp<=5||sc.event==='stone'&&!s.deck.some(c=>!c.up&&CARD[c.id].type===(i===0?'a':'s'))||i===0&&sc.event==='traveller'&&s.gold<35||i===0&&sc.event==='cliff'&&s.hp<=6||i===1&&sc.event==='master'&&!s.deck.some(c=>!c.up&&CARD[c.id].rarity>0);return `<button class="choice" data-action="event" data-key="${i}" ${disabled?'disabled':''}><strong>${title}　→</strong><small>${text}</small></button>`;}).join('')}<button class="quiet" data-action="event" data-key="2">拱手告辞</button></div>`}</div>`;}
function restPage(){return `<div class="center-box"><div class="eyebrow">${escapeHTML(game.s.scene?.place||CHAPTERS[game.chapter].place)} · 山间歇脚</div><div class="event-scene">憩</div><h2>风过松间，且歇片刻</h2><p>回复气血，或让一招更上一层。每次歇脚只能选择一项。</p><div class="rest-actions"><button class="primary" data-action="rest-heal" ${game.has('R27')?'disabled':''}><strong>调息养伤</strong><small>${game.has('R27')?'逆练铜人：无法在此疗伤':`回复${Math.floor(game.s.maxHp*.25)}气血`}</small></button><button data-action="rest-upgrade"><strong>参悟武学</strong><small>选择一张牌，永久精进</small></button></div><button class="quiet" style="margin-top:25px" data-action="finish-node">不作停留，继续赶路</button></div>`;}
function shopPage(){const s=game.s,x=s.scene.stock;return `<div class="heading"><div><div class="eyebrow">${escapeHTML(s.scene.place||CHAPTERS[game.chapter].place)} · 行商驿站</div><h2>有缘之物，待价而沽</h2><p>手中银两 ${s.gold} · 删去不再需要的基础牌，也是一种成长。</p></div><button class="primary small" data-action="finish-node">离开驿站 →</button></div><div class="shop-grid">${x.cards.map((p,i)=>`<div class="shop-product">${cardHTML({id:p.id,up:false},{read:true})}<span class="price">${p.price} 银两</span><button class="small" data-action="buy-card" data-key="${i}" ${p.sold||s.gold<p.price?'disabled':''}>${p.sold?'已售出':'购入武学'}</button></div>`).join('')}</div><div class="shop-extras"><div class="info-box">${x.relic?relicHTML(x.relic):'<h3>珍物售罄</h3>'}${x.relic?`<span class="price">${x.relicPrice} 银两</span><button data-action="buy-relic" ${x.relicSold||s.gold<x.relicPrice?'disabled':''}>${x.relicSold?'已售出':'购入奇物'}</button>`:''}</div><div class="info-box"><div class="eyebrow">去繁存精</div><h3 style="margin-top:15px">移除一张牌</h3><p>从永久牌组移除一张牌，包括心魔。每次到访限一次。</p><span class="price">60 银两</span><button data-action="remove" ${x.removed||s.gold<60?'disabled':''}>${x.removed?'本次已移除':'选择移除的牌'}</button></div></div>`;}
function endPage(){const s=game.s,won=s.phase==='win';return `<div class="center-box"><div class="eyebrow">${won?'三章已尽 · 华山论剑':'此行暂歇 · 来日再会'}</div><div class="ending-player">${playerFigure()}<h3>${escapeHTML(s.player.name)}</h3></div><h2>${won?'一身所学，终成一家':'胜负寻常，江湖未远'}</h2><p>${won?'你越过三章山水，以自己的武学登上华山绝顶。':'你的这段江湖，停在了'+CHAPTERS[game.chapter].place+'。每一次取舍，都会成为下一次出山的经验。'}</p><div class="summary-grid"><div class="info-box"><strong>${s.stats.wins}</strong><span>交锋获胜</span></div><div class="info-box"><strong>${s.stats.played}</strong><span>累计出招</span></div><div class="info-box"><strong>${s.stats.damage}</strong><span>累计气血伤害</span></div><div class="info-box"><strong>${s.stats.exhausted}</strong><span>消耗卡牌</span></div></div><div class="relic-strip" style="justify-content:center">${s.relics.map(id=>`<button class="relic-token" data-action="relic-detail" data-id="${id}">${relicIcon(id)}<span>${RELIC[id].name}</span></button>`).join('')}</div><div style="display:flex;justify-content:center;gap:12px;margin-top:28px"><button class="primary" data-action="new">再入江湖 →</button><button data-action="deck">回看此局武学</button></div><p class="version" style="margin-top:20px">此局种子 ${s.seed} · 只属于本局的江湖</p></div>`;}
function help(){return `<div class="help-grid"><div class="info-box"><h3>一局怎么走</h3><p>开局先为侠客起名、选择男女立绘；外观不影响属性或掉落。菜单可随时修改姓名与立绘。然后带着5张太祖长拳、4张抱元守一、1张吐纳和粗布药囊起步。出发前从4份随机机缘中选1份：包含通用赠礼和带代价的奖励，选定后进入地图。战斗胜利后从随机3张牌中选1张，也可以跳过；通过奖励、商店和奇遇逐步构筑牌组，流派由自己的取舍形成。新局三章各十五程，共四十五程。地图从下向上行进，只能选择亮起且与上一步相连的地点；每章中段有宝物遗藏，首领之前可歇脚。旧局保留原十八程。击败第三章首领即通关。奖励可跳过；休息可疗伤或精进；行商可以买牌、奇物和移除卡牌。</p></div><div class="info-box"><h3>怎么出牌</h3><p>先点击敌人选中目标。手机端点手牌展开完整牌面，再按“出招”确认；电脑端点击手牌直接出招。左上角是真气费用。需要选择其他手牌时，会出现选择窗口；确认后才扣真气。结束回合后存活敌人依次行动。遭遇包含单人、双人和三人阵容；先击破薄弱随从可减少每回合的围攻，群攻会命中所有存活敌人。</p></div><div class="info-box"><h3>劲力与格挡</h3><p>劲力给每段攻击增加伤害。格挡先抵挡攻击，默认在下个玩家回合开始清空。金刚不坏体可保留部分格挡；太极剑不消耗格挡。</p></div><div class="info-box"><h3>消耗、虚无与心法</h3><p>消耗：移出本场战斗的牌组循环，战后原有牌恢复。虚无：回合结束仍在手中时自动消耗，保留也无法阻止。已打出的虚无牌按其正常规则结算。心法持续整场，同名每场运起一次，不计消耗。状态气滞战后消失，心魔需移除卡牌才永久去除。</p></div><div class="info-box"><h3>毒与寒气</h3><p>中毒在敌方行动结束后扣除等量气血，格挡无法抵挡，随后中毒减少1。寒气使下回合真气减少，最多减少2，回合结束后解除。血刀吸血需要实际伤及气血；击败玄冥二老之一可拆解合击。欧阳锋半血时切换逆练招式，意图会立即更新。</p></div><div class="info-box"><h3>自损与恢复</h3><p>自损不能用格挡抵挡，也不能主动付到气血低于1。自损收益先结算，再攻击。七伤拳的代价是游戏对强行催动的改编。神照经同名每场一次，血刀回血每场两次。久战有压迫：第12回合起，敌方攻击每两回合额外增加1伤害。</p></div><div class="info-box"><h3>辅助与存档</h3><p>“辅助出招一回合”用当前手牌依照同一规则行动并结束回合，不增加属性。每次操作自动保存；菜单可导出或导入存档。手机手牌折叠在一屏内，点另一张可直接切换展开的牌面。</p></div></div><p class="muted" style="font-size:12px;margin:20px 0 0">† 为游戏拆招或据原著物品改编的名称。世界采用群侠共处的架空江湖；数值与剧情均为本游戏改编。本版无网络请求、账号或付费功能。</p>`;}
function modalBody(){
 if(!modal)return '';
 let title='',body='';
 if(modal.type==='enemy-book'){title='江湖群敌 · 立绘与招式';body=`<p class="muted">人物、势力取自金庸小说；立绘、战斗机制与数值为本游戏改编。中毒：敌方行动结束时扣等量气血，随后减少1；寒气：下回合少真气，最多减少2点。</p><div class="enemy-gallery">${ENEMIES.map(d=>`<article class="enemy-entry rank-${d.rank}">${enemyFigure(d)}<div><span class="eyebrow">第${d.chapter+1}章 · ${ENEMY_RANK[d.rank]}</span><h3>${d.name}</h3><small>${d.faction} · ${d.source} · 气血${d.hp}</small><p>${d.trait}</p><div class="enemy-moves">${d.moves.map(i=>`<div><strong>${i.label}</strong><small>${moveText(i)}</small></div>`).join('')}${d.enragedMoves?'<h4>逆练阶段 · 半血触发</h4>'+d.enragedMoves.map(i=>`<div><strong>${i.label}</strong><small>${moveText(i)}</small></div>`).join(''):''}</div></div></article>`).join('')}</div>`;}
 if(modal.type==='help'){title='初入江湖须知';body=help();}
 if(modal.type==='menu'){title='游戏设置';body=`<section class="author-contact" aria-label="联系作者"><div><small>联系作者 · 建议与反馈</small><strong>lynchrrr</strong></div><span>可选中复制</span></section><div class="choices"><button data-action="catalogue">武学与奇物图鉴</button><button data-action="enemy-book">江湖群敌与招式</button><button data-action="edit-player">修改姓名与立绘</button><button data-action="help">初入江湖须知</button><button data-action="map">查看江湖行程</button><button data-action="export">导出当前存档副本</button><label class="choice">导入存档<input type="file" id="import-save" accept="application/json,.json" style="display:block;margin-top:12px"></label><button data-action="home">回到题页</button><button class="danger" data-action="restart">结束此局，重新出山</button></div><p class="muted" style="font-size:12px">${saveError?'本机自动存档不可用，请导出副本保存。':'操作后自动保存，可随时继续。'} 导入会替换当前进度。</p>`;}
 if(modal.type==='confirm-new'){title='另起一段江湖';body='<p class="muted">开始新的一局会替换当前自动存档。你可以先回菜单导出副本。</p><button class="primary" data-action="confirm-new">开始新一局</button>';}
 if(modal.type==='map'){title='江湖行程';body=mapBoard(false);}
 if(modal.type==='log'){title='本场完整战报';body=`<div class="log-lines" style="max-height:65vh">${game.s.b.log.slice().reverse().map(x=>`<div>${x}</div>`).join('')}</div>`;}
 if(modal.type==='relics'){title=`随身奇物 · ${game.s.relics.length}`;body=`<div class="relic-options">${game.s.relics.map(id=>relicHTML(id)).join('')}</div>`;}
 if(modal.type==='relic'){title=RELIC[modal.id].name;body=`<div class="relic-detail">${relicHTML(modal.id)}</div>`;}
 if(['deck','pile','catalogue','upgrade','remove'].includes(modal.type)){
  const catalogue=modal.type==='catalogue';
  title=catalogue?`武学与奇物图鉴 · v${GAME_VERSION}`:modal.type==='deck'?`永久牌组 · ${game.s.deck.length} 张`:modal.type==='pile'?{hand:'手牌 · 完整说明',draw:'抽牌堆 · 无序展示',discard:'弃牌堆',exhaust:'消耗区 · 战后恢复'}[modal.id]:modal.type==='upgrade'?'选择永久精进的武学':'选择永久移除的牌';
  const filters=catalogue?`<div class="filters"><input id="catalogue-search" placeholder="搜索武功、来源或效果" aria-label="搜索武功" value="${filter}"><select id="path-filter" aria-label="流派筛选"><option value="">全部流派</option>${['劲力','格挡','变招','血战','连击','通用','基础'].map(x=>`<option ${pathFilter===x?'selected':''}>${x}</option>`).join('')}</select><button data-action="toggle-up">${showUp?'查看基础':'查看精进'}</button><button data-action="all-relics">30件奇物</button></div>`:'';
  let cards=catalogue?CARDS.filter(d=>(!pathFilter||d.path===pathFilter)&&(!filter||(d.name+d.source+describe({id:d.id,up:showUp})).includes(filter))).map(d=>({id:d.id,up:showUp})):modal.type==='pile'?[...game.s.b[modal.id]].sort((a,b)=>a.id.localeCompare(b.id)):game.s.deck;
  if(modal.type==='upgrade')cards=cards.filter(c=>!c.up&&!['status','curse'].includes(CARD[c.id].type));
  body=filters+(modal.type==='upgrade'?'<p class="muted">下方显示精进后的效果，点选一张即可永久精进。</p>':'')+`<div class="collection" id="catalogue-results">${cards.map(c=>cardHTML(modal.type==='upgrade'?{...c,up:true}:c,{read:!['upgrade','remove'].includes(modal.type),action:modal.type==='upgrade'?'do-upgrade':modal.type==='remove'?'do-remove':'',uid:c.uid})).join('')||'<p class="empty">没有可选武学</p>'}</div>`;
 }
 if(modal.type==='all-relics'){title='奇物图鉴 · 30 件';body=`<div class="relic-options">${RELICS.map(r=>relicHTML(r.id)).join('')}</div>`;}
 if(modal.type==='select'){
  const c=game.s.b.hand.find(x=>x.uid===pending),spec=game.selection(c);title=`${CARD[c.id].name} · ${spec.kind==='exhaust'?'选择消耗':spec.kind==='upgrade'?'选择精进':'选择保留'}`;
  body=`<p class="muted">${spec.min?'至少选择'+spec.min+'张，':''}最多选择${spec.max}张其他手牌。确认后才会出招。</p><div class="collection">${spec.candidates.map(x=>cardHTML(x,{action:'select-card',uid:x.uid,choice:true})).join('')}</div><div class="selection-footer"><span>已选择 ${selected.length} / ${spec.max}</span><button class="primary" data-action="confirm-play" ${selected.length<spec.min?'disabled':''}>确认出招 →</button></div>`;
 }
 return `<div class="modal-shade" data-testid="modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-head"><h2>${title}</h2><button data-action="close-modal" aria-label="关闭窗口">✕</button></div>${body}</section></div>`;
}
function render(){
 const previousPhase=$('.layout')?.dataset.phase,wasMap=previousPhase==='map';
 const oldTravel=$('.travel-map-scroll'),travelScroll=oldTravel?{key:oldTravel.dataset.mapKey,top:oldTravel.scrollTop}:null;
 const wasBattle=!!$('.layout[data-phase="battle"]'),handScroll=$('.hand')?.scrollLeft||0;
 const s=game.s;if(s?.phase==='map'&&!wasMap)mapViewChapter=null;if(view==='home'||s?.phase!=='battle'||!s.b.hand.some(c=>c.uid===inspectedCard))inspectedCard=null;let content;
 if(view==='home')content=home();else if(!s){view='home';content=home();}else{const pages={character:characterPage,opening:openingPage,map:mapPage,battle:battlePage,reward:rewardPage,event:eventPage,treasure:treasurePage,rest:restPage,shop:shopPage,win:endPage,lost:endPage};content=`<div class="layout" data-phase="${s.phase}">${sidebar()}<div>${header()}${saveError?'<div class="save-warning">自动存档不可用，请从菜单导出副本。</div>':''}<main class="main">${pages[s.phase]()}</main></div></div>`;}
 $('#app').innerHTML=content+modalBody();
 if(wasBattle&&s?.phase==='battle'&&$('.hand'))$('.hand').scrollLeft=handScroll;
 const travel=$('.travel-map-scroll');if(travel){if(travelScroll&&travelScroll.key===travel.dataset.mapKey)travel.scrollTop=travelScroll.top;else focusTravelMap();}
 if(previousPhase&&s&&previousPhase!==s.phase)window.scrollTo(0,0);
 const surface=$('.layout')||$('.home');if(surface)surface.inert=!!modal;
}
function focusTravelMap(){const el=$('.travel-map-scroll');if(el)el.scrollTop=Number(el.dataset.mapFocus)-el.clientHeight*.7;}
function update(){save();render();}
async function battleAction(action,{label='',type='',enemyTurn=false,auto=false}={}){
 if(combatBusy)return;
 const before=combatSnapshot(game.s),hand=$('.hand'),scroll=hand?.scrollLeft||0;
 const played=type?Array.from(document.querySelectorAll('.hand .card')).find(x=>x.getAttribute('aria-label')===label):null;
 const ghost=played?.cloneNode(true),rect=played?.getBoundingClientRect();
 const result=action();
 if(result?.ok===false){toast(result.error);return result;}
 const after=combatSnapshot(game.s),changes=combatFeedback(before,after,{enemyTurn});
 save(); // Persist the resolved action even if the page closes during its animation.
 combatBusy=true;
 const surface=$('.layout');surface?.classList.add('combat-busy');surface?.setAttribute('aria-busy','true');
 if(enemyTurn&&$('.player-intent span'))$('.player-intent span').textContent='对手出招';
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const actor=key=>key==='player'?$('.player'):document.querySelector(`.enemy[data-key="${key}"]`);
 const motions=[],effects=[];
 const motion=(el,frames,delay=0,duration=420)=>{if(el&&!reduced)motions.push(el.animate(frames,{duration,delay,easing:'ease-out',fill:'none'}).finished.catch(()=>{}));};
 const float=(el,text,kind,delay=0)=>{if(!el)return;const node=document.createElement('span');node.className='combat-float '+kind;node.textContent=text;el.append(node);effects.push(node);motion(node,[{opacity:0,transform:'translate(-50%,12px)'},{opacity:1,offset:.2,transform:'translate(-50%,-8px)'},{opacity:0,transform:'translate(-50%,-42px)'}],delay,600);};
 try{
  if(!reduced){
   if(ghost&&rect){ghost.classList.add('played-card');if(matchMedia('(max-width:900px)').matches)ghost.classList.add('folded-flight');ghost.style.cssText=`position:fixed;left:${rect.left}px;top:${rect.top}px;width:${rect.width}px;height:${rect.height}px;min-width:0;max-width:none;min-height:0;max-height:none;--hand-card-height:${rect.height}px;margin:0;z-index:80;pointer-events:none`;document.body.append(ghost);effects.push(ghost);motion(ghost,[{opacity:1,transform:'translateY(0) scale(1)'},{opacity:.9,offset:.45,transform:'translateY(-55px) scale(.93)'},{opacity:0,transform:'translateY(-110px) scale(.75)'}],0,400);}
   if(!enemyTurn||auto){motion($('.player .player-art'),type==='a'||auto?[{transform:'translateX(0)'},{transform:'translateX(18px)',offset:.4},{transform:'translateX(0)'}]:[{filter:'drop-shadow(0 0 0 transparent)'},{filter:'drop-shadow(0 0 18px #c4a569)',offset:.5},{filter:'drop-shadow(0 0 0 transparent)'}]);if(label)float($('.player'),label,'technique');}
   if(enemyTurn)before.enemies.filter(e=>e.alive).forEach((e,i)=>{const el=actor(e.key);motion(el?.querySelector('.enemy-art'),e.attacks?[{transform:'translateX(0)'},{transform:'translateX(-16px)',offset:.4},{transform:'translateX(0)'}]:[{opacity:1},{opacity:.55,offset:.5},{opacity:1}],i*120);float(el,e.label,'technique',i*120);});
   for(const change of changes){const el=actor(change.target),delay=enemyTurn?180:130;float(el,change.text,change.kind,delay);if(change.kind==='damage'){motion(el,[{filter:'brightness(1)',transform:'translateX(0)'},{filter:'brightness(1.7) sepia(.3)',transform:'translateX(-5px)',offset:.25},{filter:'brightness(1)',transform:'translateX(5px)',offset:.5},{filter:'brightness(1)',transform:'translateX(0)'}],delay,320);const slash=document.createElement('i');slash.className='combat-slash';el?.append(slash);effects.push(slash);motion(slash,[{opacity:0,transform:'rotate(-35deg) scaleX(.1)'},{opacity:1,offset:.35,transform:'rotate(-35deg) scaleX(1)'},{opacity:0,transform:'rotate(-35deg) scaleX(1.2)'}],delay,280);}if(['block','blocked'].includes(change.kind))motion(el,[{boxShadow:'inset 0 0 0 0 #8ebfc900'},{boxShadow:'inset 0 0 28px 2px #8ebfc955',offset:.5},{boxShadow:'inset 0 0 0 0 #8ebfc900'}],delay);}
   await Promise.all(motions);
  }
 }finally{effects.forEach(el=>el.remove());combatBusy=false;update();if(game.s.phase==='battle'&&$('.hand'))$('.hand').scrollLeft=scroll;}
 return result;
}
document.addEventListener('click',async ev=>{
 const el=ev.target.closest('[data-action]');if(combatBusy)return;if(!el){if(inspectedCard!==null&&!ev.target.closest('.hand,.hand-preview')){inspectedCard=null;render();}return;}if(el.disabled)return;
 const a=el.dataset.action,id=el.dataset.id,uid=Number(el.dataset.uid),key=Number(el.dataset.key);
 try{
 switch(a){
  case 'home':view='home';modal=null;render();return;
  case 'new':mapViewChapter=null;if(game.s&&!['win','lost'].includes(game.s.phase)){modal={type:'confirm-new'};}else{game.start();heroGender='male';view='game';modal=null;target=0;save();}render();return;
  case 'restart':modal={type:'confirm-new'};render();return;
  case 'confirm-new':game.start();heroGender='male';view='game';modal=null;target=0;save();render();return;
  case 'opening-choice':if(!game.chooseOpening(id))toast('这份机缘暂时无法领取');break;
  case 'opening-card':if(!game.completeOpening(game.s.opening.selected==='insight'?id:uid))toast('请选择有效的卡牌');break;
  case 'opening-back':game.backOpening();break;
  case 'opening-leave':game.leaveOpening();break;
  case 'hero-gender':if(['male','female'].includes(id)){heroGender=id;const portrait=PLAYER[game.s.character.portrait];if(portrait&&portrait.gender!==id)game.choosePlayerPortrait(null);}break;
  case 'hero-portrait':game.choosePlayerPortrait(id);break;
  case 'hero-confirm':if(!game.finishCharacter())toast(game.characterError());break;
  case 'hero-cancel':game.cancelCharacter();break;
  case 'edit-player':if(game.s.phase!=='character')game.editCharacter();heroGender=PLAYER[game.s.character?.portrait]?.gender||'male';modal=null;break;
  case 'continue':mapViewChapter=null;heroGender=PLAYER[game.s?.character?.portrait]?.gender||'male';view='game';modal=null;render();return;
  case 'menu':case 'deck':case 'relics':case 'help':case 'catalogue':case 'all-relics':case 'enemy-book':modal={type:a};render();return;
  case 'map':if(game.s.phase==='map'&&view==='game')return;modal={type:'map'};render();return;
  case 'relic-detail':modal={type:'relic',id};render();return;
  case 'close-modal':modal=null;pending=null;selected=[];render();return;
  case 'toggle-up':showUp=!showUp;render();return;
  case 'enter':game.enter(id);target=0;break;
  case 'enter-node':if(game.enterNode(id)){target=0;mapViewChapter=null;}break;
  case 'map-chapter':if(Number.isInteger(key)&&key>=0&&key<3){mapViewChapter=key;render();}return;
  case 'map-locate':mapViewChapter=game.chapter;render();focusTravelMap();return;
  case 'take-treasure':game.chooseTreasure(id);break;
  case 'target':target=key;render();return;
  case 'close-card-preview':inspectedCard=null;render();return;
  case 'play':case 'play-inspected':{
   const c=game.s.b.hand.find(x=>x.uid===uid);if(!c)return;
   if(a==='play'&&matchMedia('(max-width:900px)').matches){inspectedCard=inspectedCard===uid?null:uid;render();return;}
   const why=game.reason(c);if(why){toast(why);return;}
   inspectedCard=null;render();const spec=game.selection(c);
   if(spec.kind&&spec.candidates.length){pending=uid;selected=[];modal={type:'select'};render();return;}
   await battleAction(()=>game.play(uid,target,[]),{label:CARD[c.id].name+(c.up?'·精进':''),type:CARD[c.id].type});return;
  }
  case 'select-card':{const c=game.s.b.hand.find(x=>x.uid===pending),spec=game.selection(c);if(selected.includes(uid))selected=selected.filter(x=>x!==uid);else if(selected.length<spec.max)selected.push(uid);else toast(`最多选择${spec.max}张`);render();return;}
  case 'confirm-play':{const card=game.s.b.hand.find(c=>c.uid===pending),chosen=selected.slice(),playUid=pending;modal=null;pending=null;selected=[];render();await battleAction(()=>game.play(playUid,target,chosen),{label:CARD[card.id].name+(card.up?'·精进':''),type:CARD[card.id].type});return;}
  case 'end-turn':inspectedCard=null;render();await battleAction(()=>game.endTurn(),{enemyTurn:true});return;
  case 'auto-turn':inspectedCard=null;render();await battleAction(()=>game.autoPlayTurn(),{label:'连招',enemyTurn:true,auto:true});return;
  case 'dart':inspectedCard=null;render();await battleAction(()=>game.useDart(target),{label:'金蛇锥',type:'a'});return;
  case 'pile':modal={type:'pile',id};render();return;
  case 'battle-log':modal={type:'log'};render();return;
  case 'take-card':game.chooseRewardCard(id);break;
  case 'skip-card':game.chooseRewardCard();break;
  case 'take-relic':game.chooseRewardRelic(id);break;
  case 'skip-relic':game.chooseRewardRelic();break;
  case 'leave-reward':game.leaveReward();break;
  case 'event':if(game.s.scene.result)return;game.eventChoice(key);break;
  case 'finish-node':if(['shop','rest'].includes(game.s.phase)||game.s.phase==='treasure'&&game.s.scene.claimed||game.s.phase==='event'&&game.s.scene.result)game.finishNode();break;
  case 'rest-heal':game.rest('heal');toast('调息完毕，气血已回复');break;
  case 'rest-upgrade':modal={type:'upgrade'};render();return;
  case 'do-upgrade':if(game.rest('upgrade',uid)){modal=null;toast('武学已永久精进');}break;
  case 'buy-card':if(game.buyCard(key))toast('武学已加入牌组');break;
  case 'buy-relic':if(game.buyRelic())toast('奇物已随身携带');break;
  case 'remove':modal={type:'remove'};render();return;
  case 'do-remove':if(game.removeCard(uid)){modal=null;toast('已从永久牌组移除');}break;
  case 'export':{const blob=new Blob([JSON.stringify(game.s,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`一局江湖-${game.s.seed}.json`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出存档副本');return;}
 }
 update();
 }catch(error){console.error(error);toast('操作未完成，请关闭窗口后重试；当前进度仍保留。');}
});
document.addEventListener('keydown',e=>{if(combatBusy||e.key!=='Escape')return;if(modal){modal=null;pending=null;selected=[];render();}else if(inspectedCard!==null){inspectedCard=null;render();}});
document.addEventListener('input',e=>{if(e.target.id==='hero-name'){game.setCharacterName(e.target.value);save();const name=cleanPlayerName(e.target.value),error=game.characterError();$('#hero-name-count').textContent=Array.from(name).length+' / 12';$('#hero-preview-name').textContent=name||'待署侠名';$('#hero-form-error').textContent=error||'姓名与立绘已就绪';$('#hero-confirm').disabled=!!error;e.target.setAttribute('aria-invalid',String(!!playerNameError(e.target.value)));}if(e.target.id==='catalogue-search'){filter=e.target.value.replace(/[<>"&]/g,'');const cards=CARDS.filter(d=>(!pathFilter||d.path===pathFilter)&&(!filter||(d.name+d.source+describe({id:d.id,up:showUp})).includes(filter)));$('#catalogue-results').innerHTML=cards.map(d=>cardHTML({id:d.id,up:showUp},{read:true})).join('')||'<p class="empty">未找到相关武学</p>';}});
document.addEventListener('change',async e=>{
 if(e.target.id==='path-filter'){pathFilter=e.target.value;render();}
 if(e.target.id==='import-save'){
  try{const file=e.target.files[0];if(!file)return;if(file.size>2e6)throw Error();const s=JSON.parse(await file.text());if(!validSave(s))throw Error();game=new Game(s);inspectedCard=null;mapViewChapter=null;heroGender=PLAYER[game.s?.character?.portrait]?.gender||'male';view='game';modal=null;update();toast('存档已恢复');}catch{toast('存档格式不兼容或文件无效，原进度未变。');}
 }
});
render();
